urlset:
{% set siteUrl = "https" + "://www.awaylands.com" %}

    {{ siteUrl }}/
    {{ homepage._updatedAt }}

{% set storyPages = [stories1.items, stories2.items, stories3.items, stories4.items] %}
{% for stories in storyPages %}
  {% for story in stories %}
  {% if story.slug or story.title %}

    {{ siteUrl }}{% if story.slug %}{{ story | route('storySlug') }}{% else %}{{ story | route('story') }}{% endif %}/
    {{ story._updatedAt }}

  {% endif %}
  {% endfor %}
{% endfor %}
